<!doctype html><html><head><meta charset="utf-8"><title>Salary payment voucher</title><style>body{font:16px Arial;max-width:650px;margin:40px auto}dt{font-weight:bold;margin-top:12px} @media print{button{display:none}}</style></head><body><h2>Salary Payment Voucher — SAL-{{ $payment->id }}</h2><dl><dt>School ID</dt><dd>{{ $payment->school_id }}</dd><dt>Employee</dt><dd>{{ $slip->name }}</dd><dt>Salary month</dt><dd>{{ $slip->pay_month }}</dd><dt>Payment date</dt><dd>{{ $payment->payment_date }}</dd><dt>Amount</dt><dd>₹{{ number_format($payment->amount,2) }}</dd><dt>Mode / Reference</dt><dd>{{ $payment->payment_mode }} / {{ $payment->reference }}</dd><dt>Recorded by user ID</dt><dd>{{ $payment->paid_by }}</dd></dl><button onclick="window.print()">Print voucher</button></body></html>
